/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename in ascending (lexicographic) order — i.e. the order in which
 * they would be applied to the database.
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of .sql filenames found in `dir`, sorted in ascending
 * lexicographic order (so numeric prefixes like 001_, 002_ define run order).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of .sql filenames (basenames only).
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();                          // lexicographic sort — relies on numeric prefix convention
}

/**
 * Main entry point.  Discovers migration files and logs each one in order.
 */
function main() {
  console.log(`Migration runner starting…`);
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  const sqlFiles = getSqlFiles(MIGRATIONS_DIR);

  if (sqlFiles.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration file(s). Would apply in this order:\n`);

  sqlFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const stats    = fs.statSync(filePath);

    console.log(
      `  [${String(index + 1).padStart(3, '0')}]  ${filename}  ` +
      `(${stats.size} bytes)`
    );
  });

  console.log('\nDry-run complete. No changes were made to the database.');
}

// ─── Run ──────────────────────────────────────────────────────────────────────

main();

