    throw new Error('DATABASE_URL is not a valid URL. Check the env file.');
  }

  return {
    protocol : parsed.protocol.replace(':', ''),  // e.g. "postgres"
    host     : parsed.hostname,                    // e.g. "db.internal"
    port     : parsed.port || '5432',              // default PG port if omitted
