    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();                          // lexicographic — relies on numeric prefix convention
}

// ─── Main ─────────────────────────────────────────────────────────────────────

/**
 * Entry point.  Resolves the connection string, logs a simulated successful
 * connection, then discovers and lists migration files in run order.
 */
function main() {
  console.log('Migration runner starting…\n');

