  // The password is never read beyond this function and is never logged.
  console.log(`Protocol         : ${conn.protocol}`);
  console.log(`Host             : ${conn.host}`);
  console.log(`Port             : ${conn.port}`);
  console.log(`Database         : ${conn.database}`);
  console.log(`Password         : [redacted]`);
  console.log(`\n✔  Connected successfully to ${conn.host}:${conn.port}/${conn.database}\n`);

  // ── Step 2: discover and log migration files ───────────────────────────────
  console.log(`Migrations dir   : ${MIGRATIONS_DIR}`);
