/**
 * migrate.js
 *
 * Database migration runner.
 *
 * Reads every *.sql file from the ./migrations/ directory, sorts them
 * in lexicographic (filename) order, and logs each one it would apply.
 *
 * Ordering convention:
 *   Files must be prefixed with a zero-padded number, e.g.
 *   001_create_users.sql, 002_create_sessions.sql, …
 *   Lexicographic sort on the filename then gives the correct run order.
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql file in `dir`, sorted lexicographically by filename.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of filenames (not full paths).
 * @throws {Error} If the directory cannot be read.
 */
function getSortedMigrationFiles(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(file => path.extname(file).toLowerCase() === SQL_EXTENSION)
    .sort(); // lexicographic — relies on numeric prefix convention
}

/**
 * Validates that a filename follows the expected numeric-prefix pattern
 * (e.g. "001_create_users.sql").  Warns but does not abort on violations.
 *
 * @param {string} filename
 */
function warnIfBadName(filename) {
  const EXPECTED = /^\d+_.+\.sql$/i;
  if (!EXPECTED.test(filename)) {
    console.warn(
      `  [WARN] "${filename}" does not follow the "NNN_description.sql" ` +
      `naming convention — ordering may be unreliable.`
    );
  }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

/**
 * Entry point: discovers and logs migration files in the order they
 * would be applied.
 */
function main() {
  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);

  // ── Discover files ──────────────────────────────────────────────────────────
  const files = getSortedMigrationFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log('\nNo migration files found — nothing to apply.');
    return;
  }

  console.log(`Migrations found     : ${files.length}\n`);
  console.log('Migrations to apply (in order):');
  console.log('─'.repeat(40));

  // ── Log each file ───────────────────────────────────────────────────────────
  files.forEach((filename, index) => {
    warnIfBadName(filename);

    const filePath = path.join(MIGRATIONS_DIR, filename);
    const stats    = fs.statSync(filePath);
    const sizeKB   = (stats.size / 1024).toFixed(2);

    console.log(
      `  [${String(index + 1).padStart(3, '0')}] ${filename}` +
      `  (${sizeKB} KB)`
    );
  });

  console.log('─'.repeat(40));
  console.log(`\nDry run complete. ${files.length} migration(s) would be applied.`);
  console.log('\nTo execute for real, integrate each file with your DB client,');
  console.log("e.g. pass fs.readFileSync(filePath, 'utf8') to client.query().");
}

main();

