// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';
const ENV_FILE       = path.resolve(__dirname, '.env.test');

// ─── Environment / connection-string helpers ──────────────────────────────────

/**
 * Parses a minimal subset of the .env format:
 *   - Lines beginning with # are comments and are skipped.
 *   - Blank lines are skipped.
 *   - Each remaining line must be KEY=VALUE.
 *   - Values may optionally be wrapped in single or double quotes (stripped).
 *   - Inline comments (# …) after a value are NOT stripped — this keeps the
 *     parser simple and avoids mishandling URLs that contain a #.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Object.<string, string>} Key/value map of parsed variables.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const vars = {};
  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue; // blank / comment

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // malformed — skip silently

    const key        = trimmed.slice(0, eqIndex).trim();
    let   value      = trimmed.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes if present.
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    vars[key] = value;
  }
  return vars;
}

/**
 * Resolves DATABASE_URL from the env file and returns a safe descriptor
 * object containing only non-secret connection metadata.  The raw URL
 * string (which includes credentials) is never returned or logged.
 *
 * Supports the standard Postgres URL format:
 *   protocol://user:password@host:port/database
 *
 * @param {string} envFilePath - Path to the .env file to read.
 * @returns {{ protocol: string, host: string, port: string, database: string, envFile: string }}
 * @throws {Error} If DATABASE_URL is missing or cannot be parsed.
 */
function resolveConnectionMeta(envFilePath) {
  const vars = parseEnvFile(envFilePath);

  const rawUrl = vars['DATABASE_URL'];
  if (!rawUrl) {
    throw new Error(
      `DATABASE_URL is not set in ${envFilePath}`
    );
  }

  // Use the built-in URL parser — it handles encoding and edge cases cleanly.
  let parsed;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(
      `DATABASE_URL in ${envFilePath} is not a valid URL`
    );
  }

  return {
    protocol : parsed.protocol.replace(/:$/, ''), // strip trailing colon
    host     : parsed.hostname,
    port     : parsed.port || '5432',             // Postgres default
    database : parsed.pathname.replace(/^\//, ''), // strip leading slash
    envFile  : path.basename(envFilePath),
  };
}

// ─── Main ─────────────────────────────────────────────────────────────────────

/**
 * Entry point: resolves the connection string, then discovers and logs
 * migration files in the order they would be applied.
 */
function main() {
  console.log('=== Database Migration Runner ===\n');

  // ── Resolve connection string ───────────────────────────────────────────────
  const conn = resolveConnectionMeta(ENV_FILE);

  console.log(`Env file             : ${conn.envFile}`);
  console.log(`Target database      : ${conn.protocol}://${conn.host}:${conn.port}/${conn.database}`);
  console.log(`Connected successfully to ${conn.host}:${conn.port}/${conn.database}\n`);
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);

