/**
 * Returns every *.sql file in `dir`, sorted lexicographically by filename.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of filenames (not full paths).
 * @throws {Error} If the directory cannot be read.
 */
function getSortedMigrationFiles(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(file => path.extname(file).toLowerCase() === SQL_EXTENSION)
    .sort(); // lexicographic — relies on numeric prefix convention
}

/**
 * Validates that a filename follows the expected numeric-prefix pattern
 * (e.g. "001_create_users.sql").  Warns but does not abort on violations.
 *
 * @param {string} filename
 */
function warnIfBadName(filename) {
  const EXPECTED = /^\d+_.+\.sql$/i;
  if (!EXPECTED.test(filename)) {
    console.warn(
      `  [WARN] "${filename}" does not follow the "NNN_description.sql" ` +
      `naming convention — ordering may be unreliable.`
    );
  }
}

