function main() {
  console.log('=== Database Migration Runner ===\n');

  // ── Resolve connection string ───────────────────────────────────────────────
  const conn = resolveConnectionMeta(ENV_FILE);

  console.log(`Env file             : ${conn.envFile}`);
  console.log(`Target database      : ${conn.protocol}://${conn.host}:${conn.port}/${conn.database}`);
  console.log(`Connected successfully to ${conn.host}:${conn.port}/${conn.database}\n`);
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);

  // ── Discover files ──────────────────────────────────────────────────────────
  const files = getSortedMigrationFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log('\nNo migration files found — nothing to apply.');
    return;
  }

  console.log(`Migrations found     : ${files.length}\n`);
  console.log('Migrations to apply (in order):');
  console.log('─'.repeat(40));

  // ── Log each file ───────────────────────────────────────────────────────────
  files.forEach((filename, index) => {
    warnIfBadName(filename);

    const filePath = path.join(MIGRATIONS_DIR, filename);
    const stats    = fs.statSync(filePath);
    const sizeKB   = (stats.size / 1024).toFixed(2);

    console.log(
      `  [${String(index + 1).padStart(3, '0')}] ${filename}` +
      `  (${sizeKB} KB)`
    );
  });

  console.log('─'.repeat(40));
  console.log(`\nDry run complete. ${files.length} migration(s) would be applied.`);
  console.log('\nTo execute for real, integrate each file with your DB client,');
  console.log("e.g. pass fs.readFileSync(filePath, 'utf8') to client.query().");
}

