  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  // ── Step 2: Discover migration files ──────────────────────────────────────
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  let files;

  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((filename, index) => {
