/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename in the order it would be applied (lexicographic / numeric order).
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dry-run      # (default behaviour — log only, no DB writes)
 *   node migrate.js --dir ./other  # override the migrations directory
 *
 * Exit codes:
 *   0  – success (or nothing to apply)
 *   1  – the migrations directory does not exist or cannot be read
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

/**
 * Parse a minimal set of CLI flags:
 *   --dir <path>   directory that contains the *.sql migration files
 *   --dry-run      explicitly state that no DB changes will be made
 */
function parseArgs(argv) {
  const args = { dir: './migrations', dryRun: true };

  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--dir' && argv[i + 1]) {
      args.dir = argv[++i];
    } else if (argv[i] === '--dry-run') {
      args.dryRun = true;
    }
  }

  return args;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Return every *.sql file inside `dir`, sorted lexicographically so that a
 * numeric prefix scheme (001_, 002_, …) yields a deterministic apply order.
 *
 * @param {string} dir - Absolute or relative path to the migrations directory.
 * @returns {{ name: string, fullPath: string }[]}
 */
function getMigrationFiles(dir) {
  const absDir = path.resolve(dir);

  if (!fs.existsSync(absDir)) {
    throw new Error(`Migrations directory not found: ${absDir}`);
  }

  const stat = fs.statSync(absDir);
  if (!stat.isDirectory()) {
    throw new Error(`Path is not a directory: ${absDir}`);
  }

  const files = fs
    .readdirSync(absDir)
    .filter((f) => f.endsWith('.sql'))
    .sort()                                       // lexicographic → numeric prefix order
    .map((name) => ({ name, fullPath: path.join(absDir, name) }));

  return files;
}

/**
 * Read and return the SQL content of a single migration file.
 *
 * @param {string} fullPath
 * @returns {string}
 */
function readMigration(fullPath) {
  return fs.readFileSync(fullPath, 'utf8');
}

// ─── Core runner ──────────────────────────────────────────────────────────────

/**
 * Log (and optionally apply) each migration in order.
 *
 * @param {string}  dir    - Path to the migrations directory.
 * @param {boolean} dryRun - When true, only log — never touch a database.
 */
function runMigrations(dir, dryRun) {
  console.log('─'.repeat(60));
  console.log('  Database Migration Runner');
  console.log('─'.repeat(60));
  console.log(`  Directory : ${path.resolve(dir)}`);
  console.log(`  Mode      : ${dryRun ? 'dry-run (log only)' : 'apply'}`);
  console.log('─'.repeat(60));

  let files;
  try {
    files = getMigrationFiles(dir);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('\n  No *.sql migration files found — nothing to apply.\n');
    return;
  }

  console.log(`\n  Found ${files.length} migration(s):\n`);

  files.forEach((file, index) => {
    const sql     = readMigration(file.fullPath);
    const lines   = sql.split('\n').length;
    const preview = sql
      .split('\n')
      .find((l) => l.trim() && !l.trim().startsWith('--')) // first non-comment line
      ?.trim()
      .slice(0, 60)                                         // cap preview length
      ?? '(empty)';

    console.log(`  [${String(index + 1).padStart(2, '0')}] ${file.name}`);
    console.log(`       Lines   : ${lines}`);
    console.log(`       Preview : ${preview}${preview.length === 60 ? '…' : ''}`);

    if (!dryRun) {
      // Real implementation would execute `sql` against your DB client here, e.g.:
      //   await db.query(sql);
      console.log('       Status  : ✔ applied');
    } else {
      console.log('       Status  : ⏭  skipped (dry-run)');
    }

    console.log();
  });

  console.log('─'.repeat(60));
  console.log(
    dryRun
      ? '  Dry-run complete. No changes were made to the database.'
      : `  ${files.length} migration(s) applied successfully.`
  );
  console.log('─'.repeat(60) + '\n');
}

// ─── Entry point ──────────────────────────────────────────────────────────────

const { dir, dryRun } = parseArgs(process.argv);
runMigrations(dir, dryRun);

