/**
 * Parse a minimal set of CLI flags:
 *   --dir <path>   directory that contains the *.sql migration files
 *   --env <path>   .env file to load DATABASE_URL from (default: .env.test)
 *   --dry-run      explicitly state that no DB changes will be made
 */
function parseArgs(argv) {
  const args = { dir: './migrations', env: './.env.test', dryRun: true };

  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--dir' && argv[i + 1]) {
      args.dir = argv[++i];
    } else if (argv[i] === '--env' && argv[i + 1]) {
      args.env = argv[++i];
    } else if (argv[i] === '--dry-run') {
      args.dryRun = true;
    }
  }

  return args;
}

// ─── Environment / connection-string resolution ───────────────────────────────

/**
 * Parse a .env file into a plain key→value object.
 *
 * Handles:
 *  - Full-line comments  (# …)
 *  - Blank lines
 *  - Optional surrounding quotes on values  ("val" | 'val')
 *  - Inline comments are intentionally NOT stripped — they are part of the
 *    value for any real dotenv parser too, keeping behaviour predictable.
 *
 * @param {string} envPath - Path to the .env file.
 * @returns {Record<string, string>}
 */
function loadEnvFile(envPath) {
  const absPath = path.resolve(envPath);

  if (!fs.existsSync(absPath)) {
    throw new Error(`Env file not found: ${absPath}`);
  }

  const raw = fs.readFileSync(absPath, 'utf8');
  const env = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and full-line comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;                       // no '=' → not a key=value pair

    const key   = trimmed.slice(0, eqIdx).trim();
    let   value = trimmed.slice(eqIdx + 1).trim();

    // Strip optional surrounding quotes.
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

/**
 * Resolve and validate DATABASE_URL from a parsed env object.
 *
 * Returns two strings:
 *  - `connectionString`  — the raw URL, used only for the (simulated) connect call.
 *  - `displayUrl`        — password replaced with '****', safe to log.
 *
 * @param {Record<string, string>} env
 * @returns {{ connectionString: string, displayUrl: string }}
 */
function resolveConnectionString(env) {
  const raw = env['DATABASE_URL'];

  if (!raw) {
    throw new Error('DATABASE_URL is not defined in the env file.');
  }

  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    throw new Error(`DATABASE_URL is not a valid URL: "${raw}"`);
  }

  // Build a display-safe version: blank the password field before serialising.
  const safe = new URL(raw);          // independent copy
  if (safe.password) {
    safe.password = '****';
  }

  return {
    connectionString: raw,            // never logged — passed only to connectToDatabase()
    displayUrl:       safe.toString(),
  };
}

/**
 * Simulate opening a database connection.
 * No real network call is made; this function only logs the outcome.
 *
 * @param {string} _connectionString - Raw DATABASE_URL (used by a real client).
 * @param {string}  displayUrl       - Redacted URL that is safe to log.
 */
function connectToDatabase(_connectionString, displayUrl) {
  // ── In a real implementation you would do something like: ──────────────────
  //   const client = new pg.Client({ connectionString: _connectionString });
  //   await client.connect();
  // ──────────────────────────────────────────────────────────────────────────
  console.log(`  Connected : ✔ connected to ${displayUrl}`);
}

/**
 * Log (and optionally apply) each migration in order.
 *
 * @param {string}  dir    - Path to the migrations directory.
 * @param {string}  env    - Path to the .env file containing DATABASE_URL.
 * @param {boolean} dryRun - When true, only log — never touch a database.
 */
function runMigrations(dir, env, dryRun) {
  console.log('─'.repeat(60));
  console.log('  Database Migration Runner');
  console.log('─'.repeat(60));
  console.log(`  Env file  : ${path.resolve(env)}`);
  console.log(`  Directory : ${path.resolve(dir)}`);
  console.log(`  Mode      : ${dryRun ? 'dry-run (log only)' : 'apply'}`);
  console.log('─'.repeat(60));

  // ── Step 1: resolve the connection string ──────────────────────────────────
  let connectionString, displayUrl;
  try {
    const envVars = loadEnvFile(env);
    ({ connectionString, displayUrl } = resolveConnectionString(envVars));
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log();
  connectToDatabase(connectionString, displayUrl);
  console.log();
  console.log('─'.repeat(60));

