 */
function getMigrationFiles(dir) {
  const absDir = path.resolve(dir);

  if (!fs.existsSync(absDir)) {
    throw new Error(`Migrations directory not found: ${absDir}`);
  }

  const stat = fs.statSync(absDir);
  if (!stat.isDirectory()) {
    throw new Error(`Path is not a directory: ${absDir}`);
  }

  const files = fs
    .readdirSync(absDir)
    .filter((f) => f.endsWith('.sql'))
    .sort()                                       // lexicographic → numeric prefix order
    .map((name) => ({ name, fullPath: path.join(absDir, name) }));

  return files;
}

/**
 * Read and return the SQL content of a single migration file.
 *
 * @param {string} fullPath
 * @returns {string}
 */
function readMigration(fullPath) {
  return fs.readFileSync(fullPath, 'utf8');
}

