    }

    console.log();
  });

  console.log('─'.repeat(60));
  console.log(
    dryRun
      ? '  Dry-run complete. No changes were made to the database.'
      : `  ${files.length} migration(s) applied successfully.`
  );
  console.log('─'.repeat(60) + '\n');
