// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const ENV_FILE       = path.resolve(__dirname, process.env.ENV_FILE ?? '.env.test');

// ─── .env parser ─────────────────────────────────────────────────────────────

/**
 * Minimal .env parser — no external dependencies required.
 *
 * Supports:
 *   - KEY=value
 *   - KEY="quoted value"  /  KEY='quoted value'
 *   - Inline # comments
 *   - Blank lines and lines that start with # are skipped
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  let raw;

  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blanks and full-line comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;                          // no '=' → skip

    const key = trimmed.slice(0, eqIndex).trim();
    let   val = trimmed.slice(eqIndex + 1).trim();

    // Strip an optional inline comment that follows a bare (unquoted) value
    // e.g.  KEY=somevalue  # comment
    const isQuoted = (val.startsWith('"') && val.endsWith('"'))
                  || (val.startsWith("'") && val.endsWith("'"));

    if (isQuoted) {
      val = val.slice(1, -1);                              // remove surrounding quotes
    } else {
      val = val.split(/\s+#/)[0].trim();                  // strip inline comment
    }

    if (key) result[key] = val;
  }

  return result;
}

// ─── Connection-string helpers ────────────────────────────────────────────────

/**
 * Resolves DATABASE_URL from the env file.
 *
 * @param {string} envFilePath
 * @returns {string} The raw DATABASE_URL value.
 */
function resolveDatabaseUrl(envFilePath) {
  const vars = parseEnvFile(envFilePath);

  if (!vars.DATABASE_URL) {
    throw new Error(`DATABASE_URL not found in ${envFilePath}`);
  }

  return vars.DATABASE_URL;
}

/**
 * Returns a copy of a connection URL with the password replaced by '***'.
 * Safe to print to stdout or include in log files.
 *
 * postgres://user:secret@host:5432/db  →  postgres://user:***@host:5432/db
 *
 * @param {string} rawUrl
 * @returns {string} Redacted URL string.
 */
function redactUrl(rawUrl) {
  try {
    const parsed = new URL(rawUrl);
    if (parsed.password) parsed.password = '***';
    return parsed.toString();
  } catch {
    // Not a parseable URL — mask the whole thing rather than leak anything
    return '<unparseable-url>';
  }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log(`\nMigration runner`);
  console.log(`Directory : ${MIGRATIONS_DIR}`);
  console.log('─'.repeat(60));

  // ── Step 1: resolve & log the database connection ──────────────────────────
