/**
 * Returns every .sql file inside `dir`, sorted in ascending order so that
 * migrations are applied in the correct sequence (001 → 002 → 003 …).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (not full paths).
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith(SQL_EXTENSION))
    .map(entry => entry.name)
    .sort(); // lexicographic sort — relies on numeric prefixes (001_, 002_ …)

  return sqlFiles;
}

/**
 * Reads the contents of a single SQL file.
 *
 * @param {string} dir      - Absolute path to the migrations directory.
 * @param {string} filename - The SQL filename to read.
 * @returns {string} The raw SQL text.
 */
function readSqlFile(dir, filename) {
  const fullPath = path.join(dir, filename);
