/** Env file to load — can be overridden with --env-file <path> at runtime. */
const DEFAULT_ENV_FILE = '.env.test';

// ─── Env-file parser ──────────────────────────────────────────────────────────

/**
 * Minimal .env parser — no third-party dependencies required.
 *
 * Handles:
 *   - `KEY=value` and `KEY="quoted value"` / `KEY='quoted value'`
 *   - Inline `# comments` after a value
 *   - Full-line comments (`# …`) and blank lines (both are skipped)
 *
 * Does NOT mutate `process.env`; returns a plain object so the caller
 * decides which keys to use.
 *
 * @param {string} filePath - Absolute path to the .env-style file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const raw  = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  for (const rawLine of raw.split('\n')) {
    const line = rawLine.trim();

    // Skip blank lines and full-line comments.
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue; // malformed — no '=' present

    const key      = line.slice(0, eqIndex).trim();
    let   rawValue = line.slice(eqIndex + 1).trim();

    // Strip inline comment that follows an unquoted value  (key=val # comment)
    // but only when the value is not wrapped in quotes.
    if (!rawValue.startsWith('"') && !rawValue.startsWith("'")) {
      const commentIdx = rawValue.indexOf(' #');
      if (commentIdx !== -1) rawValue = rawValue.slice(0, commentIdx).trim();
    }

    // Strip matching surrounding quotes.
    if (
      (rawValue.startsWith('"')  && rawValue.endsWith('"'))  ||
      (rawValue.startsWith("'") && rawValue.endsWith("'"))
    ) {
      rawValue = rawValue.slice(1, -1);
    }

    if (key) vars[key] = rawValue;
  }

  return vars;
}

// ─── Connection-string helpers ────────────────────────────────────────────────

/**
 * Parses a PostgreSQL-style connection URL into its structural components.
 *
 * Expected format:
 *   protocol://user:password@host:port/database
 *
 * @param {string} url - The raw DATABASE_URL string.
 * @returns {{ protocol: string, user: string, password: string,
 *             host: string, port: string, database: string }}
 * @throws {Error} If the URL cannot be parsed.
 */
function parseDatabaseUrl(url) {
  // Use the built-in WHATWG URL parser — no regex fragility.
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error(`DATABASE_URL is not a valid URL: "${url}"`);
  }

  return {
    protocol : parsed.protocol.replace(/:$/, ''), // strip trailing ':'
    user     : decodeURIComponent(parsed.username),
    password : decodeURIComponent(parsed.password),
    host     : parsed.hostname,
    port     : parsed.port || '5432',
    database : parsed.pathname.replace(/^\//, ''), // strip leading '/'
  };
}

/**
 * Returns a copy of the connection URL with the password replaced by '****'
 * so it is safe to write to any log or console output.
 *
 * @param {string} url - The raw DATABASE_URL string.
 * @returns {string} The redacted URL.
 */
function redactDatabaseUrl(url) {
  try {
    const copy = new URL(url);
    if (copy.password) copy.password = '****';
    return copy.toString();
  } catch {
    // If parsing fails here we still don't want to leak anything.
    return '<unparseable-url>';
  }
