  const env = parseEnvFile(envFilePath);

  if (!env.DATABASE_URL) {
    throw new Error(`DATABASE_URL is not defined in ${envFilePath}`);
  }

  const { host, port, database, user } = parseDatabaseUrl(env.DATABASE_URL);
  const redactedUrl = redactDatabaseUrl(env.DATABASE_URL);

  return { redactedUrl, host, port, database, user };
}

