 * @returns {string[]} Sorted array of .sql filenames (basenames only).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Could not read migrations directory: ${err.message}`);
  }

  return entries
    .filter(name => name.endsWith('.sql'))   // only SQL files
    .sort();                                  // ascending lexicographic order
