-- Migration 003: Add avatar column to users
ALTER TABLE users
  ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(512);

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (version) order.
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./path/to/migrations   # optional custom directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/**
 * Resolve the migrations directory from an optional CLI flag or fall back to
 * the default `./migrations` folder next to this script.
 *
 * Accepted flag formats:
 *   --dir ./custom/path
 *   --dir=./custom/path
 */
function resolveMigrationsDir(args) {
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--dir' && args[i + 1]) {
      return path.resolve(args[i + 1]);
    }
    const match = args[i].match(/^--dir=(.+)$/);
    if (match) {
      return path.resolve(match[1]);
    }
  }
  // Default: ./migrations/ relative to this script
  return path.resolve(__dirname, 'migrations');
}

// ---------------------------------------------------------------------------
// Core logic
// ---------------------------------------------------------------------------

/**
 * Returns all *.sql files inside `dir`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) determine the application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of .sql filenames (basenames only).
 * @throws {Error}     If the directory cannot be read.
 */
function collectMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  const sqlFiles = entries.filter((name) => name.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    throw new Error(`No .sql files found in: ${dir}`);
  }

  // Lexicographic sort — numeric prefixes (001_, 002_, …) keep natural order.
  return sqlFiles.sort();
}

/**
 * Validates that every file in `filenames` is actually readable.
 * Returns an array of error messages (empty when all files are OK).
 *
 * @param {string}   dir       - Absolute path to the migrations directory.
 * @param {string[]} filenames - Sorted list of migration filenames.
 * @returns {string[]} Validation errors, if any.
 */
function validateFiles(dir, filenames) {
  const errors = [];

  for (const filename of filenames) {
    const fullPath = path.join(dir, filename);
    try {
      fs.accessSync(fullPath, fs.constants.R_OK);
    } catch {
      errors.push(`  ✗  Cannot read file: ${fullPath}`);
    }
  }

  return errors;
}

/**
 * Logs each migration filename that would be applied, in order.
 *
 * @param {string}   dir       - Absolute path to the migrations directory.
 * @param {string[]} filenames - Sorted list of migration filenames.
 */
function logMigrations(dir, filenames) {
  console.log(`\nMigrations directory : ${dir}`);
  console.log(`Migrations found     : ${filenames.length}\n`);
  console.log('Applying migrations in order:');
  console.log('─'.repeat(50));

  filenames.forEach((filename, index) => {
    const position = String(index + 1).padStart(2, '0');
    console.log(`  [${position}] ${filename}`);
  });

  console.log('─'.repeat(50));
  console.log(`\n✓ Would apply ${filenames.length} migration(s). Done.\n`);
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

function main() {
  const args = process.argv.slice(2);
  const migrationsDir = resolveMigrationsDir(args);

  let filenames;

  // 1. Collect
  try {
    filenames = collectMigrationFiles(migrationsDir);
  } catch (err) {
    console.error(`\n✗ Error: ${err.message}\n`);
    process.exit(1);
  }

  // 2. Validate readability
  const errors = validateFiles(migrationsDir, filenames);
  if (errors.length > 0) {
    console.error('\n✗ Some migration files could not be read:');
    errors.forEach((e) => console.error(e));
    console.error('');
    process.exit(1);
  }

  // 3. Log
  logMigrations(migrationsDir, filenames);
}

main();

