/**
 * migrate.js
 *
 * Resolves DATABASE_URL from a .env file, logs a simulated successful
 * connection, then reads all *.sql files from the ./migrations/ directory
 * and logs each filename it would apply, in lexicographic (version) order.
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./path/to/migrations   # optional custom directory
 *   node migrate.js --env ./.env.staging          # optional custom env file
 *   node migrate.js --dir=./migrations --env=./.env.test
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration — CLI flag resolution
// ---------------------------------------------------------------------------

/**
 * Finds the value of a named CLI flag in the argument list.
 * Accepts two formats:  --flag value   and   --flag=value
 *
 * @param {string[]} args     - process.argv slice to search.
 * @param {string}   flagName - Flag name with dashes, e.g. '--dir'.
 * @returns {string|null} The flag value, or null when the flag is absent.
 */
function resolveFlag(args, flagName) {
  for (let i = 0; i < args.length; i++) {
    // --flag value
    if (args[i] === flagName && args[i + 1] !== undefined) {
      return args[i + 1];
    }
    // --flag=value  (build the prefix string without template literals so the
    // Edit tool cannot accidentally corrupt it)
    const prefix = flagName + '=';
    if (args[i].startsWith(prefix)) {
      return args[i].slice(prefix.length);
    }
  }
  return null;
}

/**
 * Returns the absolute path to the migrations directory.
 * Source priority: --dir flag → default ./migrations/.
 *
 * @param {string[]} args - process.argv slice.
 * @returns {string} Absolute path.
 */
function resolveMigrationsDir(args) {
  const flag = resolveFlag(args, '--dir');
  return flag ? path.resolve(flag) : path.resolve(__dirname, 'migrations');
}

/**
 * Returns the absolute path to the .env file.
 * Source priority: --env flag → default ./.env.test.
 *
 * @param {string[]} args - process.argv slice.
 * @returns {string} Absolute path.
 */
function resolveEnvFile(args) {
  const flag = resolveFlag(args, '--env');
  return flag ? path.resolve(flag) : path.resolve(__dirname, '.env.test');
}

// ---------------------------------------------------------------------------
// .env parsing and connection-string resolution
// ---------------------------------------------------------------------------

/**
 * Parses a .env file into a plain key→value object.
 *
 * Supported syntax:
 *   KEY=value
 *   KEY="double-quoted value"
 *   KEY='single-quoted value'
 *   # comment lines and blank lines are ignored
 *
 * @param {string} envPath - Absolute path to the .env file.
 * @returns {Object.<string, string>} Parsed key/value pairs.
 * @throws {Error} If the file is missing or cannot be read.
 */
function parseEnvFile(envPath) {
  let raw;
  try {
    raw = fs.readFileSync(envPath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error('Env file not found: ' + envPath);
    }
    throw new Error('Failed to read env file: ' + err.message);
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;                     // no '=' → not a key/value pair

    const key   = trimmed.slice(0, eqIndex).trim();
    let   value = trimmed.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    result[key] = value;
  }

  return result;
}

/**
 * Extracts and validates DATABASE_URL from a parsed env object.
 * Validation checks that the value begins with a recognised DB scheme;
 * it does not attempt a real network connection.
 *
 * @param {Object.<string, string>} env     - Parsed key/value pairs.
 * @param {string}                  envPath - Source file path (for error messages).
 * @returns {string} The raw DATABASE_URL value.
 * @throws {Error}   If the key is absent or the value has no recognised scheme.
 */
function resolveDatabaseUrl(env, envPath) {
  const url = env['DATABASE_URL'];

  if (!url) {
    throw new Error('DATABASE_URL is not defined in ' + envPath);
  }

  const knownSchemes = ['postgres://', 'postgresql://', 'mysql://', 'sqlite://', 'mssql://'];
  const hasKnownScheme = knownSchemes.some(function (scheme) {
    return url.startsWith(scheme);
  });

  if (!hasKnownScheme) {
    throw new Error(
      'DATABASE_URL in ' + envPath + ' does not start with a recognised scheme ' +
      '(' + knownSchemes.join(', ') + ')'
    );
  }

  return url;
}

/**
 * Returns a version of a connection string safe for logging.
 * The password segment (`:password@`) is replaced with `:***@` so that the
 * host, port, and database name remain visible for diagnostics while the
 * credential is never written to the console.
 *
 * Examples
 *   postgres://admin:s3cr3t@db.internal:5432/prod  →  postgres://admin:***@db.internal:5432/prod
 *   postgres://db.internal/prod                    →  postgres://db.internal/prod  (unchanged)
 *
 * @param {string} url - Raw connection string.
 * @returns {string} Redacted connection string.
 */
function redactConnectionString(url) {
  // Captures:  scheme://userinfo:password@  and replaces password with ***
  return url.replace(
    /^([a-z][a-z0-9+\-.]*:\/\/[^:@/]+):([^@]+)@/,
    '$1:***@'
  );
}

/**
 * Loads DATABASE_URL from the resolved env file, validates it, and logs a
 * simulated successful connection message.  The password is redacted before
 * being printed; no real network call is made.
 *
 * @param {string} envPath - Absolute path to the .env file.
 * @returns {string} The raw DATABASE_URL (available for downstream use).
 */
function loadAndLogConnection(envPath) {
  console.log('Loading env file : ' + envPath);

  const env         = parseEnvFile(envPath);
  const databaseUrl = resolveDatabaseUrl(env, envPath);
  const redactedUrl = redactConnectionString(databaseUrl);

  console.log('Database URL     : ' + redactedUrl);
  console.log('✓ Connected to database successfully.');

  return databaseUrl;
}

// ---------------------------------------------------------------------------
// Core migration logic
// ---------------------------------------------------------------------------

/**
 * Returns all *.sql files inside `dir`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) enforce the correct application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of .sql filenames (basenames only).
 * @throws {Error}     If the directory does not exist or cannot be read.
 */
function collectMigrationFiles(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error('Migrations directory not found: ' + dir);
    }
    throw new Error('Failed to read migrations directory: ' + err.message);
  }

  const sqlFiles = entries.filter(function (name) {
    return name.endsWith('.sql');
  });

  if (sqlFiles.length === 0) {
    throw new Error('No .sql files found in: ' + dir);
  }

  return sqlFiles.sort();   // lexicographic — numeric prefixes keep natural order
}

/**
 * Checks that every file in `filenames` is readable by the current process.
 *
 * @param {string}   dir       - Absolute path to the migrations directory.
 * @param {string[]} filenames - Sorted list of migration filenames.
 * @returns {string[]} Validation error messages (empty array when all pass).
 */
function validateFiles(dir, filenames) {
  const errors = [];
  for (const filename of filenames) {
    const fullPath = path.join(dir, filename);
    try {
      fs.accessSync(fullPath, fs.constants.R_OK);
    } catch (_) {
      errors.push('  ✗  Cannot read file: ' + fullPath);
    }
  }
  return errors;
}

/**
 * Logs each migration filename that would be applied, in order.
 *
 * @param {string}   dir       - Absolute path to the migrations directory.
 * @param {string[]} filenames - Sorted list of migration filenames.
 */
function logMigrations(dir, filenames) {
  console.log('');
  console.log('Migrations directory : ' + dir);
  console.log('Migrations found     : ' + filenames.length);
  console.log('');
  console.log('Applying migrations in order:');
  console.log('─'.repeat(50));

  filenames.forEach(function (filename, index) {
    const position = String(index + 1).padStart(2, '0');
    console.log('  [' + position + '] ' + filename);
  });

  console.log('─'.repeat(50));
  console.log('');
  console.log('✓ Would apply ' + filenames.length + ' migration(s). Done.');
  console.log('');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

function main() {
  const args          = process.argv.slice(2);
  const envFile       = resolveEnvFile(args);
  const migrationsDir = resolveMigrationsDir(args);

  // 1. Resolve and log the database connection
  try {
    loadAndLogConnection(envFile);
  } catch (err) {
    console.error('\n✗ Connection error: ' + err.message + '\n');
    process.exit(1);
  }

  // 2. Collect migration files
  let filenames;
  try {
    filenames = collectMigrationFiles(migrationsDir);
  } catch (err) {
    console.error('\n✗ Error: ' + err.message + '\n');
    process.exit(1);
  }

  // 3. Validate that every file can be read before logging anything
  const errors = validateFiles(migrationsDir, filenames);
  if (errors.length > 0) {
    console.error('\n✗ Some migration files could not be read:');
    errors.forEach(function (e) { console.error(e); });

