/**
 * migrate.js
 *
 * Scans ./migrations/ for *.sql files, sorts them into lexicographic order
 * (which keeps numeric prefixes like 001_, 002_ ... in the right sequence),
 * and logs each filename it *would* apply.
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql file inside `dir`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) guarantee a stable, predictable order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of filenames (not full paths).
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(file => path.extname(file).toLowerCase() === SQL_EXTENSION)
    .sort();                          // lexicographic sort — relies on numeric prefixes
}

/**
 * Pretty-prints the ordered list of migration files that would be applied.
 *
 * @param {string[]} files - Sorted list of SQL filenames.
 */
function logMigrationPlan(files) {
  if (files.length === 0) {
    console.log('No migration files found — nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) in: ${MIGRATIONS_DIR}`);
  console.log('─'.repeat(55));

  files.forEach((file, index) => {
    // Pad the step number so columns stay aligned for up to 999 migrations.
    const step = String(index + 1).padStart(3, '0');
    console.log(`  [${step}] ${file}`);
  });

  console.log('─'.repeat(55));
  console.log(`Migrations would be applied in the order shown above.`);
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');

  let sqlFiles;

  try {
    sqlFiles = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }

  logMigrationPlan(sqlFiles);
}

main();

