// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';
const ENV_FILE       = path.resolve(__dirname, process.env.ENV_FILE || '.env.test');

// ─── .env parsing ─────────────────────────────────────────────────────────────

/**
 * Minimal, dependency-free .env parser.
 *
 * Handles:
 *   - KEY=value
 *   - KEY="quoted value"  /  KEY='quoted value'
 *   - Inline # comments
 *   - Blank lines and full-line comments
 *
 * Does NOT mutate process.env — returns a plain object so the caller decides
 * what to do with the values.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  let raw;

  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const result = {};

  for (const line of raw.split('\n')) {
    // Strip leading/trailing whitespace, skip blanks and comments.
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;                      // no '=' → not a valid pair

    const key   = trimmed.slice(0, eqIndex).trim();
    let   value = trimmed.slice(eqIndex + 1).trim();

    // Strip an inline comment that is not inside quotes.
    // e.g.  KEY=value  # this part is ignored
    const commentMatch = value.match(/^([^#'"]*?)\s*#.*$/);
    if (commentMatch) value = commentMatch[1].trim();

    // Remove surrounding quotes (single or double), if present.
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) result[key] = value;
  }

  return result;
}

// ─── Connection-string resolution ─────────────────────────────────────────────

/**
 * Reads DATABASE_URL from the parsed env and returns only the safe,
 * non-secret fields needed for a connection log entry.
 *
 * Safe fields: protocol, host, port, database name.
 * Intentionally omitted: username, password, query-string options.
 *
 * @param {Record<string, string>} env - Object returned by parseEnvFile().
 * @returns {{ protocol: string, host: string, port: string, database: string }}
 */
function resolveConnection(env) {
  const raw = env['DATABASE_URL'];

  if (!raw) {
    throw new Error('DATABASE_URL is not defined in the env file.');
  }

  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    throw new Error('DATABASE_URL is not a valid URL.');
  }

  return {
    protocol : parsed.protocol.replace(/:$/, ''),   // e.g. "postgres"
    host     : parsed.hostname,                      // e.g. "db.internal"
    port     : parsed.port || defaultPort(parsed.protocol),
    database : parsed.pathname.replace(/^\//, ''),   // strip leading "/"
  };
}

/**
 * Returns the conventional default port for known database protocols.
 *
 * @param {string} protocol - Value from URL.protocol (includes trailing colon).
 * @returns {string}
 */
function defaultPort(protocol) {
  const defaults = {
    'postgres:' : '5432',
    'postgresql:': '5432',
    'mysql:'    : '3306',
    'mariadb:'  : '3306',
    'mssql:'    : '1433',
    'mongodb:'  : '27017',
  };
  return defaults[protocol] ?? 'unknown';
}

/**
 * Logs a safe, human-readable connection summary.
 * The password and full connection string are never printed.
 *
 * @param {ReturnType<typeof resolveConnection>} conn
 * @param {string} envFilePath - Path to the env file (for context in the log).
 */
function logConnection(conn, envFilePath) {
  console.log(`  Env file  : ${envFilePath}`);
  console.log(`  Protocol  : ${conn.protocol}`);
  console.log(`  Host      : ${conn.host}`);
  console.log(`  Port      : ${conn.port}`);
  console.log(`  Database  : ${conn.database}`);
  console.log(`  Password  : ${'*'.repeat(8)}  (redacted)`);
  console.log();
  console.log('✓ Connected to database successfully (simulated).');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');

  // ── Step 1: resolve the database connection ──────────────────────────────
  console.log('── Step 1: Resolving database connection ──');

  let env, conn;

  try {
    env  = parseEnvFile(ENV_FILE);
    conn = resolveConnection(env);
  } catch (err) {
    console.error(`Connection error: ${err.message}`);
    process.exit(1);
  }

  logConnection(conn, ENV_FILE);

  // ── Step 2: discover migration files ─────────────────────────────────────
  console.log('\n── Step 2: Discovering migrations ────────');

  let sqlFiles;

  try {
    sqlFiles = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }

  logMigrationPlan(sqlFiles);
}

main();

