#!/usr/bin/env node
/**
 * migrate.js — Database migration runner
 *
 * Reads *.sql files from ./migrations/, sorts them into a deterministic
 * order, and logs each filename it would apply.
 *
 * Ordering rules (applied in priority order):
 *   1. Files whose names start with a numeric prefix (e.g. 001_, 002_)
 *      are sorted numerically by that prefix.
 *   2. Files without a numeric prefix follow after, sorted alphabetically.
 *
 * Usage:
 *   node migrate.js                  # default ./migrations directory
 *   node migrate.js ./other/dir      # custom migrations directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.join(__dirname, 'migrations');

const SQL_EXTENSION = '.sql';

// ── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Extracts the leading integer prefix from a filename, if present.
 * e.g. "003_add_column.sql" → 3
 *      "add_column.sql"     → null
 *
 * @param {string} filename
 * @returns {number|null}
 */
function numericPrefix(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : null;
}

/**
 * Comparator that sorts SQL migration filenames in a stable,
 * deterministic order (numeric prefix first, then alphabetical).
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function migrationComparator(a, b) {
  const na = numericPrefix(a);
  const nb = numericPrefix(b);

  if (na !== null && nb !== null) return na - nb;   // both numeric  → numeric order
  if (na !== null)                return -1;         // only a numeric → a comes first
  if (nb !== null)                return  1;         // only b numeric → b comes first
  return a.localeCompare(b);                         // neither numeric → alphabetical
}

/**
 * Reads and validates the migrations directory.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {{ dir: string, files: string[] }} Sorted list of .sql filenames.
 * @throws If the directory does not exist or cannot be read.
 */
function loadMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const stat = fs.statSync(dir);
  if (!stat.isDirectory()) {
    throw new Error(`Path is not a directory: ${dir}`);
  }

  const files = fs
    .readdirSync(dir)
    .filter(f => path.extname(f).toLowerCase() === SQL_EXTENSION)
    .sort(migrationComparator);

  return files;
}

// ── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory : ${MIGRATIONS_DIR}\n`);

  let files;

  try {
    files = loadMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No SQL migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) — applying in order:\n`);

  files.forEach((filename, index) => {
    const position    = String(index + 1).padStart(String(files.length).length, '0');
    const fullPath    = path.join(MIGRATIONS_DIR, filename);
    const { size }    = fs.statSync(fullPath);

    console.log(`  [${position}/${files.length}] ${filename}  (${size} bytes)`);
  });

  console.log('\nDone — all migrations logged successfully.');
}

main();

