const SQL_EXTENSION = '.sql';

/**
 * Reads an .env file and returns the value of DATABASE_URL.
 *
 * Parsing rules:
 *   - Lines beginning with # are treated as comments and skipped.
 *   - Blank lines are skipped.
 *   - Only the key DATABASE_URL is extracted; all other keys are ignored
 *     so unrelated secrets are never loaded into memory.
 *   - Optional surrounding quotes (" or ') on the value are stripped.
 *
 * @param {string} envFile - Absolute path to the .env file.
 * @returns {string} The raw DATABASE_URL value.
 * @throws If the file is missing, unreadable, or DATABASE_URL is absent.
 */
function resolveConnectionString(envFile) {
  if (!fs.existsSync(envFile)) {
    throw new Error(`Env file not found: ${envFile}`);
  }

  const lines = fs.readFileSync(envFile, 'utf8').split('\n');

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip comments and blank lines
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    // Only act on the DATABASE_URL key
    if (!trimmed.startsWith('DATABASE_URL=')) continue;

    const raw = trimmed.slice('DATABASE_URL='.length).trim();

    // Strip optional surrounding quotes
    const value = raw.replace(/^(["'])(.*)\1$/, '$2');

    if (!value) {
      throw new Error('DATABASE_URL is present in env file but has no value.');
    }

    return value;
  }

  throw new Error(`DATABASE_URL not found in env file: ${envFile}`);
}

/**
 * Parses a PostgreSQL / generic database connection URL and returns a
 * log-safe descriptor.  The password is redacted before the object is
 * returned — it never appears in any string that will be printed.
 *
 * Supported schemes: postgres, postgresql, mysql, sqlite, mssql, mongodb.
 *
 * @param {string} rawUrl - The raw connection URL (e.g. from DATABASE_URL).
 * @returns {{ scheme: string, host: string, port: string, database: string, user: string, safeUrl: string }}
 * @throws If the URL cannot be parsed.
 */
function parseConnectionUrl(rawUrl) {
  let parsed;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(`DATABASE_URL is not a valid URL: ${rawUrl}`);
  }

  const scheme   = parsed.protocol.replace(/:$/, '');           // e.g. "postgres"
  const host     = parsed.hostname || '(none)';
  const port     = parsed.port     || '(default)';
  const database = parsed.pathname.replace(/^\//, '') || '(none)';  // strip leading /
  const user     = parsed.username || '(none)';

  // Build a redacted URL for safe logging: replace password with asterisks
  const redacted = new URL(rawUrl);
  if (redacted.password) redacted.password = '********';
  const safeUrl = redacted.toString();

  return { scheme, host, port, database, user, safeUrl };
}

