// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const ENV_FILE       = path.resolve(__dirname, process.argv[2] ?? '.env.test');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parses a .env file and returns a plain object of key → value pairs.
 * Supports:
 *   - `KEY=value` and `KEY="value"` / `KEY='value'` (quotes are stripped)
 *   - Inline `#` comments
 *   - Blank lines and full-line `#` comments (both are skipped)
 *
 * The file is never `require()`-d or eval-d; it is read as plain text so
 * that no value is inadvertently executed or leaked to child processes.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  return lines.reduce((acc, raw) => {
    const line = raw.trim();

    // Skip blank lines and full-line comments.
    if (!line || line.startsWith('#')) return acc;

    // Split only on the FIRST `=` so values containing `=` are preserved.
    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) return acc;

    const key        = line.slice(0, eqIndex).trim();
    // Strip an optional trailing inline comment, then remove surrounding quotes.
    const rawValue   = line.slice(eqIndex + 1).replace(/#.*$/, '').trim();
    const value      = rawValue.replace(/^(['"])(.*)\1$/, '$2');

    if (key) acc[key] = value;
    return acc;
  }, {});
}

/**
 * Extracts the protocol and host from a connection URL without exposing
 * credentials (username, password) or other sensitive path components.
 *
 * For a URL such as:
 *   postgres://user:secret@db.internal:5432/mydb
 * this returns:
 *   { protocol: 'postgres', host: 'db.internal', port: '5432' }
 *
 * @param {string} urlString - The raw connection URL.
 * @returns {{ protocol: string, host: string, port: string }} Safe metadata.
 */
function safeConnectionInfo(urlString) {
  // Use the built-in URL parser — no regex needed, no accidental capture of secrets.
  const parsed = new URL(urlString);
  return {
    protocol: parsed.protocol.replace(/:$/, ''), // strip trailing colon
    host:     parsed.hostname,
    port:     parsed.port || '(default)',
  };
}

/**
 * Resolves and validates DATABASE_URL from the parsed env object.
 *
 * @param {Record<string, string>} env - Parsed env key/value pairs.
 * @returns {string} The raw connection URL string.
 */
function resolveConnectionString(env) {
  const url = env['DATABASE_URL'];
  if (!url) {
    throw new Error('DATABASE_URL is not defined in the env file.');
  }

  // Validate that it is a well-formed URL before returning it.
  try {
    new URL(url);
  } catch {
    throw new Error('DATABASE_URL is not a valid URL.');
  }

  return url;
}

// ─── Main ─────────────────────────────────────────────────────────────────────

