/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs the
 * filenames in the order they would be applied (lexicographic / numeric
 * prefix order).
 *
 * Usage:
 *   node migrate.js              – dry-run: list files that would be applied
 *   node migrate.js --verbose    – also print each file's SQL content
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const VERBOSE        = process.argv.includes('--verbose');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of absolute paths to every *.sql file inside `dir`,
 * sorted lexicographically so that numeric prefixes (001_, 002_, …) define
 * the application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of absolute file paths.
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort(); // lexicographic sort — relies on numeric prefixes like 001_, 002_

  return sqlFiles;
}

/**
 * Logs a formatted banner to stdout.
 *
 * @param {string} message
 */
function banner(message) {
  const line = '─'.repeat(message.length + 4);
  console.log(`\n┌${line}┐`);
  console.log(`│  ${message}  │`);
  console.log(`└${line}┘\n`);
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  banner('Database Migration Runner  (dry-run)');

  // 1. Discover migration files
  let files;
  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('[INFO]  No *.sql migration files found — nothing to apply.');
    return;
  }

  console.log(`[INFO]  Found ${files.length} migration file(s) in: ${MIGRATIONS_DIR}\n`);

  // 2. Log each file in order
  files.forEach((filename, index) => {
    const absolutePath = path.join(MIGRATIONS_DIR, filename);
    const stepLabel    = String(index + 1).padStart(3, '0');

    console.log(`  [${stepLabel}] Would apply: ${filename}`);

    // Optional: print the SQL content when --verbose is supplied
    if (VERBOSE) {
      const sql = fs.readFileSync(absolutePath, 'utf8').trim();
      const indented = sql
        .split('\n')
        .map(line => `         ${line}`)
        .join('\n');
      console.log(indented);
      console.log(); // blank line between files
    }
  });

  console.log(`\n[INFO]  Dry-run complete. ${files.length} migration(s) would be applied in the order shown above.`);
  console.log('[INFO]  Remove the dry-run guard and integrate a DB client to execute for real.\n');
}

main();

