-- Migration 003: Add role column to users
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role VARCHAR(50) NOT NULL DEFAULT 'member';

/**
 * migrate.js
 *
 * Reads all .sql files from the ./migrations/ directory and logs each
 * filename in the order it would be applied (ascending lexicographic order,
 * which matches the numeric prefix convention: 001_, 002_, …).
 *
 * Usage:
 *   node migrate.js              – dry-run (logs filenames only)
 *   node migrate.js --dry-run    – same explicit flag
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of .sql filenames from the given directory,
 * sorted in ascending order (001_… before 002_… etc.).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of SQL filenames.
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith(SQL_EXTENSION))
    .map(entry => entry.name)
    .sort(); // lexicographic sort — relies on numeric prefix (001_, 002_, …)

  return sqlFiles;
}

/**
 * Validates that a filename follows the expected numeric-prefix convention.
 * Expected pattern: NNN_description.sql  (e.g. 001_create_users.sql)
 *
 * @param {string} filename
 * @returns {boolean}
 */
function isValidMigrationName(filename) {
  return /^\d+_.+\.sql$/.test(filename);
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner (dry-run) ===\n');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  let files;

  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  // ── Warn about any files that don't follow the naming convention ───────────
  const invalidFiles = files.filter(f => !isValidMigrationName(f));
  if (invalidFiles.length > 0) {
    console.warn('[WARN] The following files do not match the expected pattern');
    console.warn('       (NNN_description.sql) and will be skipped:\n');
    invalidFiles.forEach(f => console.warn(`  ✖  ${f}`));
    console.warn('');
  }

  const validFiles = files.filter(isValidMigrationName);

  if (validFiles.length === 0) {
    console.log('No valid migration files to apply after filtering.');
    return;
  }

  console.log(`Found ${validFiles.length} migration(s) to apply:\n`);

  validFiles.forEach((filename, index) => {
    const stepNumber   = String(index + 1).padStart(3, '0');
    const absolutePath = path.join(MIGRATIONS_DIR, filename);
    const stats        = fs.statSync(absolutePath);
    const sizeKB       = (stats.size / 1024).toFixed(2);

    console.log(`  [${stepNumber}] ${filename}  (${sizeKB} KB)`);
  });

  console.log('\nDry-run complete. No changes were made to the database.');
  console.log('Remove the --dry-run flag and connect a DB client to apply.');
}

main();

