 *
 * Usage:
 *   node migrate.js                        – uses .env.test
 *   node migrate.js --env-file=.env.local  – override env file
 *   node migrate.js --dry-run              – explicit dry-run flag
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR  = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION   = '.sql';
const DEFAULT_ENV_FILE = '.env.test';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parses a .env file into a plain key/value object.
 *
 * Supported syntax:
 *   - KEY=value          plain assignment
 *   - KEY="value"        double-quoted value (quotes stripped)
 *   - KEY='value'        single-quoted value (quotes stripped)
 *   - # comment lines    ignored
 *   - blank lines        ignored
 *   - inline # comments  everything after an unquoted # is stripped
 *
 * The parser is intentionally minimal — it handles the real-world cases
 * that appear in .env files without pulling in a third-party dependency.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const raw  = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  for (const rawLine of raw.split('\n')) {
    // Strip leading/trailing whitespace and skip blanks or comment lines.
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    // Split only on the first '=' so values may contain '=' themselves.
    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key        = line.slice(0, eqIndex).trim();
    let   rawValue   = line.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes.
    if (
      (rawValue.startsWith('"') && rawValue.endsWith('"')) ||
      (rawValue.startsWith("'") && rawValue.endsWith("'"))
    ) {
      rawValue = rawValue.slice(1, -1);
    } else {
      // Strip inline comments (unquoted values only).
      const commentIdx = rawValue.indexOf(' #');
      if (commentIdx !== -1) rawValue = rawValue.slice(0, commentIdx).trim();
    }

    if (key) vars[key] = rawValue;
  }

  return vars;
}

/**
 * Resolves DATABASE_URL from the specified env file.
 * Raises a clear error when the file is missing or the key is absent.
 *
 * @param {string} envFilePath - Path to the .env file.
 * @returns {string} The raw DATABASE_URL value.
 */
function resolveDatabaseUrl(envFilePath) {
  const vars = parseEnvFile(envFilePath);

  if (!vars.DATABASE_URL) {
    throw new Error(`DATABASE_URL is not defined in ${envFilePath}`);
  }

  return vars.DATABASE_URL;
}

/**
 * Redacts the password from a postgres:// or postgresql:// connection string
