  expires_at TIMESTAMPTZ NOT NULL
);

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (numerical) order.
 *
 * Usage:
 *   node migrate.js
 *
 * How it works:
 *  1. Read every *.sql file from ./migrations/, sorted alphabetically so that
 *     the numeric prefixes (001_, 002_, …) define the execution order.
 *  2. For each file, log the filename and a preview of its SQL content.
 *  3. In a real implementation you would open a DB connection here and execute
 *     the SQL inside a transaction, rolling back if any statement fails.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql file inside `dir`, sorted alphabetically.
 * Alphabetical order on zero-padded numeric prefixes (001_, 002_, …) equals
 * chronological migration order.
 *
 * @param {string} dir  Absolute path to the migrations directory.
 * @returns {string[]}  Sorted list of full file paths.
 */
function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const files = fs
    .readdirSync(dir)
    .filter((file) => file.endsWith(SQL_EXTENSION))
    .sort(); // lexicographic sort — relies on zero-padded numeric prefixes

  if (files.length === 0) {
    throw new Error(`No ${SQL_EXTENSION} files found in: ${dir}`);
  }

  return files.map((file) => path.join(dir, file));
}

/**
 * Returns a short, single-line preview of a SQL file's content, useful for
 * log output without flooding the terminal.
 *
 * @param {string} filePath  Absolute path to the SQL file.
 * @param {number} maxLength Maximum number of characters to include.
 * @returns {string}
 */
function getSqlPreview(filePath, maxLength = 72) {
  const raw = fs.readFileSync(filePath, 'utf8');

  // Collapse whitespace so the preview fits on one line
  const oneLine = raw.replace(/\s+/g, ' ').trim();

  return oneLine.length > maxLength
    ? `${oneLine.slice(0, maxLength)}…`
    : oneLine;
}

// ─── Core migration runner ────────────────────────────────────────────────────

/**
 * Simulates running all pending migrations in order.
 * Logs each filename (and a SQL preview) before it would be applied.
 *
 * Replace the body of this function with real DB calls to make it live:
 *
 *   const client = await pool.connect();
 *   try {
 *     await client.query('BEGIN');
 *     await client.query(sql);
 *     await client.query('COMMIT');
 *   } catch (err) {
 *     await client.query('ROLLBACK');
 *     throw err;
 *   } finally {
 *     client.release();
 *   }
 */
function runMigrations() {
  console.log('='.repeat(60));
  console.log('Database Migration Runner');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}`);
  console.log('='.repeat(60));

  let migrationFiles;

  try {
    migrationFiles = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log(`\nFound ${migrationFiles.length} migration(s) to apply:\n`);

  migrationFiles.forEach((filePath, index) => {
    const filename   = path.basename(filePath);
    const stepNumber = String(index + 1).padStart(2, '0');
    const preview    = getSqlPreview(filePath);

    console.log(`  [${stepNumber}] Applying: ${filename}`);
    console.log(`       Preview: ${preview}`);
    console.log();

    /*
     * ── REAL IMPLEMENTATION HOOK ──────────────────────────────────────
     * const sql = fs.readFileSync(filePath, 'utf8');
     * await db.query(sql);           // execute inside a transaction
     * await recordAppliedMigration(filename); // mark as done in DB
     * ─────────────────────────────────────────────────────────────────
     */
  });

  console.log('='.repeat(60));
  console.log(`All ${migrationFiles.length} migration(s) logged successfully.`);
  console.log('='.repeat(60));
}

// ─── Entry point ─────────────────────────────────────────────────────────────

runMigrations();

