/**
 * Parses a .env-style file and returns its key/value pairs as a plain object.
 * Handles:
 *  - Full-line comments beginning with #
 *  - Inline comments after a value (anything following an unquoted #)
 *  - Optional surrounding whitespace around the = delimiter
 *  - Optional single or double quotes wrapping the value
 *  - Blank lines (silently skipped)
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`.env file not found: ${filePath}`);
  }

  const vars = {};

  fs.readFileSync(filePath, 'utf8')
    .split('\n')
    .forEach((rawLine, lineNumber) => {
      const line = rawLine.trim();

      // Skip blank lines and full-line comments
      if (line === '' || line.startsWith('#')) return;

      const delimiterIndex = line.indexOf('=');
      if (delimiterIndex === -1) {
        throw new Error(
          `Malformed .env entry at line ${lineNumber + 1}: "${line}"`
        );
      }

      const key = line.slice(0, delimiterIndex).trim();

      // Everything after the first '=', before any trailing inline comment
      let value = line.slice(delimiterIndex + 1).trim();

      // Strip optional surrounding quotes (both styles)
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      } else {
        // Remove inline comment (unquoted value): treat '#' as comment start
        const commentIndex = value.indexOf(' #');
        if (commentIndex !== -1) {
          value = value.slice(0, commentIndex).trim();
        }
      }

      vars[key] = value;
    });

  return vars;
}

/**
 * Resolves DATABASE_URL by checking, in priority order:
 *  1. The process environment (already-set env vars win, e.g. CI/CD pipelines)
 *  2. The parsed .env file at `envFilePath`
 *
 * @param {string} envFilePath  Absolute path to the .env file to fall back on.
 * @returns {string}  The resolved connection string.
 */
function resolveDatabaseUrl(envFilePath) {
  if (process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  const vars = parseEnvFile(envFilePath);

  if (!vars.DATABASE_URL) {
    throw new Error(`DATABASE_URL not found in ${envFilePath}`);
  }

  return vars.DATABASE_URL;
}

/**
 * Builds a display-safe version of a connection URL by replacing the password
 * segment (://user:PASS@host) with a fixed mask, so credentials are never
 * written to logs or stdout.
 *
 * Input:  postgres://admin:s3cr3t@db.internal:5432/production
 * Output: postgres://admin:***@db.internal:5432/production
 *
 * Falls back to the scheme + host only if the URL cannot be parsed.
 *
 * @param {string} connectionString  Raw DATABASE_URL value.
 * @returns {string}  Redacted URL safe for logging.
 */
function redactConnectionString(connectionString) {
  try {
    const url = new URL(connectionString);
    // Replace the password in-place; username is not sensitive in logs
    url.password = '***';
    return url.toString();
  } catch {
    // URL couldn't be parsed — return only what we know is safe
    return '<unparseable connection string>';
  }
}

/**
 * Simulates opening a database connection.
 * Resolves DATABASE_URL from the environment or an .env file, then logs a
 * success message with the password redacted.
 *
 * @param {string} envFilePath  .env file to read if DATABASE_URL is not in env.
 * @returns {string}  The resolved (raw) connection string for downstream use.
