  const connectionString = resolveDatabaseUrl(envFilePath);
  const redacted         = redactConnectionString(connectionString);

  console.log(`  Connected to database: ${redacted}`);

  /*
   * ── REAL IMPLEMENTATION HOOK ────────────────────────────────────────
   * const pool = new Pool({ connectionString });
   * await pool.query('SELECT 1');   // lightweight liveness check
   * return pool;
   * ────────────────────────────────────────────────────────────────────
   */

  return connectionString;
