 *   } catch (err) {
 *     await client.query('ROLLBACK');
 *     throw err;
 *   } finally {
 *     client.release();
 *   }
 */
function runMigrations() {
  console.log('='.repeat(60));
  console.log('Database Migration Runner');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}`);
  console.log('='.repeat(60));

