/**
 * migrate.js
 *
 * Reads DATABASE_URL from a .env file, simulates a database connection, then
 * reads every *.sql file from the ./migrations/ directory and logs each
 * filename in the order it would be applied (lexicographic / numeric prefix).
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./custom/migrations
 *   node migrate.js --env .env.production
 *   node migrate.js --dir ./custom/migrations --env .env.staging
 *
 * Exit codes:
 *   0  – completed successfully (or nothing to do)
 *   1  – unrecoverable error (env file missing, DATABASE_URL absent,
 *         migrations directory missing, unreadable file, etc.)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// CLI helpers
// ---------------------------------------------------------------------------

/**
 * Returns the value that follows `flag` in process.argv, or `null` if the
 * flag is absent or has no subsequent argument.
 *
 * @param {string} flag  e.g. '--dir'
 * @returns {string|null}
 */
function getFlag(flag) {
  const idx = process.argv.indexOf(flag);
  if (idx !== -1 && process.argv[idx + 1]) {
    return process.argv[idx + 1];
  }
  return null;
}

/**
 * Returns the absolute path to the migrations directory.
 * Resolved from --dir <path>, or defaults to ./migrations.
 *
 * @returns {string}
 */
function getMigrationsDir() {
  const override = getFlag('--dir');
  return override
    ? path.resolve(override)
    : path.resolve(__dirname, 'migrations');
}

/**
 * Returns the absolute path to the .env file to load.
 * Resolved from --env <path>, or defaults to .env.test.
 *
 * @returns {string}
 */
function getEnvFilePath() {
  const override = getFlag('--env');
  return override
    ? path.resolve(override)
    : path.resolve(__dirname, '.env.test');
}

// ---------------------------------------------------------------------------
// .env parser
// ---------------------------------------------------------------------------

/**
 * Parses a .env-style file into a plain key/value object.
 *
 * Supported syntax:
 *   KEY=value          plain value
 *   KEY="value"        double-quoted (quotes stripped)
 *   KEY='value'        single-quoted (quotes stripped)
 *   # comment          ignored
 *   (blank lines)      ignored
 *
 * Values are never written to process.env; they are returned only to the
 * caller so that nothing leaks into the wider process environment.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Object.<string, string>}  Parsed key/value pairs.
 * @throws  {Error}  If the file cannot be read.
 */
function loadEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw new Error(`Could not read env file "${filePath}": ${err.message}`);
  }

  const result = {};

  for (const line of raw.split('\n')) {
    // Strip inline comments and surrounding whitespace
    const trimmed = line.trim();

    // Skip blank lines and full-line comments
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    // Match KEY=value, KEY="value", or KEY='value'
    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(['"]?)(.+?)\2\s*$/);
    if (!match) continue;

    const key   = match[1];
    const value = match[3];

    result[key] = value;
  }

  return result;
}

// ---------------------------------------------------------------------------
// Connection string resolution
// ---------------------------------------------------------------------------

/**
 * Replaces the userinfo portion of a connection URL (everything between
 * "://" and "@") with "***" so the string is safe to log.
 *
 * postgres://user:password@host:5432/db  →  postgres://***@host:5432/db
 * mysql://user:password@host/db          →  mysql://***@host/db
 * If the URL contains no "@" (no credentials) it is returned unchanged.
 *
 * @param {string} url
 * @returns {string}
 */
function redactConnectionString(url) {
  // Replace everything between "://" and the last "@" before the host
  return url.replace(/(:[/]{2})[^@]+@/, '$1***@');
}

/**
 * Loads the env file, extracts DATABASE_URL, validates it, and returns both
 * the raw URL (for a real driver) and a redacted URL (safe to log).
 *
 * @returns {{ raw: string, redacted: string, envPath: string }}
 * @throws  {Error}  If the env file is unreadable or DATABASE_URL is missing.
 */
function resolveConnectionString() {
  const envPath = getEnvFilePath();

  let env;
  try {
    env = loadEnvFile(envPath);
  } catch (err) {
    throw err; // already has a descriptive message
  }

  const raw = env['DATABASE_URL'];

  if (!raw) {
    throw new Error(
      `DATABASE_URL is not defined in "${envPath}". ` +
      'Add DATABASE_URL=<connection-string> to that file.'
    );
  }

  if (raw.trim() === '') {
    throw new Error(`DATABASE_URL is set but empty in "${envPath}".`);
  }

  return {
    raw,                                   // kept for real driver usage
    redacted: redactConnectionString(raw), // safe to print
    envPath,
  };
}

// ---------------------------------------------------------------------------
// Migration file helpers
// ---------------------------------------------------------------------------

/**
 * Returns true when a filename should be treated as a migration.
