/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (numeric-prefix) order.
 *
 * Usage:
 *   node migrate.js
 *
 * Conventions expected for migration files:
 *   - Stored in ./migrations/
 *   - Named with a numeric prefix so lexicographic order equals intended
 *     application order, e.g. 001_create_users.sql, 002_create_posts.sql
 *   - File extension must be .sql
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of .sql filenames found in `dir`, sorted lexicographically
 * so that numeric prefixes (001_, 002_, …) produce the correct run order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of SQL filenames (basenames, not full paths).
 * @throws {Error} If the directory cannot be read.
 */
function getSortedMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  const sqlFiles = entries.filter(
    (entry) =>
      path.extname(entry).toLowerCase() === SQL_EXTENSION &&
      fs.statSync(path.join(dir, entry)).isFile()
  );

  // Lexicographic sort — relies on zero-padded numeric prefixes (001, 002, …)
  return sqlFiles.sort();
}

// ─── Main ─────────────────────────────────────────────────────────────────────

