  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  let files;

  try {
    files = getSortedMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((filename, index) => {
    const step     = String(index + 1).padStart(3, '0');
    const fullPath = path.join(MIGRATIONS_DIR, filename);

    // Log the file that would be applied.
