 *   - Lines starting with # are comments and are ignored
 *   - Blank lines are ignored
 *   - Inline comments (KEY=value # note) are NOT supported by design —
 *     the entire text after `=` is the value, which avoids misparse bugs
 *     with URLs that contain `#` fragments.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Object.<string, string>} Parsed key/value pairs.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(filePath) {
  let raw;

  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw new Error(`Failed to read env file: ${err.message}`);
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) continue; // skip malformed lines without '='

    const key   = trimmed.slice(0, separatorIndex).trim();
    let   value = trimmed.slice(separatorIndex + 1).trim();

    // Strip matching surrounding quotes, if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) result[key] = value;
  }

  return result;
}

