function parseDatabaseUrl(url) {
  try {
    const parsed = new URL(url);

    if (!['postgres:', 'postgresql:'].includes(parsed.protocol)) {
      return null;
    }

    return {
      host:     parsed.hostname || '(unknown host)',
      port:     parsed.port     || '5432',            // Postgres default
