/**
 * migrate.js
 *
 * 1. Reads DATABASE_URL from a .env file (defaults to .env.test) and logs a
 *    simulated successful connection using a redacted form of the URL so that
 *    credentials are never printed in plain text.
 * 2. Reads all .sql files from the ./migrations/ directory and logs each
 *    filename it would apply, in ascending (chronological) order.
 *
 * Ordering is determined lexicographically on the filename, which works
 * correctly when files are prefixed with zero-padded sequence numbers
 * (e.g. 001_, 002_, 003_).
 *
 * Usage:
 *   node migrate.js
 *   ENV_FILE=.env.production node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE       = path.resolve(__dirname, process.env.ENV_FILE ?? '.env.test');
const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── .env parser ─────────────────────────────────────────────────────────────

/**
 * Parses a .env file into a plain key/value object.
 *
 * Supported syntax:
 *   - KEY=value
 *   - KEY="quoted value"   (double-quoted)
 *   - KEY='quoted value'   (single-quoted)
 *   - # comment lines and blank lines are ignored
 *   - Inline comments (KEY=value # comment) are NOT stripped to avoid
 *     ambiguity with values that legitimately contain `#`.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw new Error(`Could not read env file: ${err.message}`);
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments.
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // malformed line — no '=' present

    const key   = trimmed.slice(0, eqIndex).trim();
    let   value = trimmed.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes (single or double).
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) result[key] = value;
  }

  return result;
}

// ─── Connection-string helpers ────────────────────────────────────────────────

/**
 * Resolves DATABASE_URL from the parsed env object.
 *
 * @param {Record<string, string>} env - Parsed key/value pairs from the env file.
 * @returns {string} The raw connection string.
 * @throws {Error} If DATABASE_URL is missing or empty.
 */
function resolveConnectionString(env) {
  const url = env['DATABASE_URL'];
  if (!url) {
    throw new Error(
      'DATABASE_URL is not set. Ensure it is defined in the env file.'
    );
  }
  return url;
}

/**
 * Returns a copy of the connection URL with the password replaced by
 * '***' so it is safe to print in logs.
 *
 * Uses the WHATWG URL API (built-in since Node 10) which handles all
 * percent-encoding and edge cases correctly.
 *
 * @param {string} rawUrl - The original connection string.
 * @returns {string} The redacted URL string.
 * @throws {Error} If the string is not a valid URL.
 */
function redactPassword(rawUrl) {
  let parsed;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(`DATABASE_URL is not a valid URL.`);
  }

  if (parsed.password) {
    parsed.password = '***';
  }

  return parsed.toString();
}

// ─── Migrations helper ────────────────────────────────────────────────────────

/**
 * Returns every .sql filename inside `dir`, sorted lexicographically so that
 * numerically-prefixed files are applied in the correct order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basenames only).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Could not read migrations directory: ${err.message}`);
  }

  return entries
    .filter(file => path.extname(file).toLowerCase() === SQL_EXTENSION)
    .sort(); // lexicographic sort — relies on zero-padded numeric prefixes
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('Migration runner started.');
  console.log(`Env file:            ${ENV_FILE}`);
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  // ── Step 1: resolve the connection string ──────────────────────────────────
  let connectionString;

  try {
    const env      = parseEnvFile(ENV_FILE);
    connectionString = resolveConnectionString(env);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  // Redact the password before logging — credentials must never appear in logs.
  let safeUrl;
  try {
    safeUrl = redactPassword(connectionString);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  console.log(`Connecting to database...`);
  console.log(`  URL: ${safeUrl}`);
  console.log(`Connected successfully.\n`);

  // ── Step 2: collect and log migration files ────────────────────────────────
  let sqlFiles;

  try {
    sqlFiles = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

  sqlFiles.forEach((file, index) => {
    const position = String(index + 1).padStart(String(sqlFiles.length).length, ' ');
    const filePath = path.join(MIGRATIONS_DIR, file);
    console.log(`  [${position}/${sqlFiles.length}] ${file}`);
    console.log(`         → ${filePath}`);
  });

  console.log('\nDry run complete. No changes were made to the database.');
}

main();

