-- Migration 003: Add role column to users
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role VARCHAR(50) NOT NULL DEFAULT 'member';

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename (in sorted order) that would be applied as a migration.
 *
 * Usage:
 *   node migrate.js
 *
 * Conventions enforced:
 *   - Only files with a .sql extension are considered.
 *   - Files are applied in ascending lexicographic order, so a numeric
 *     prefix (e.g. 001_, 002_, …) keeps them in the intended sequence.
 *   - An empty migrations/ directory is treated as a no-op, not an error.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every .sql file inside `dir`, sorted lexicographically.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (not full paths).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    if (err.code === 'ENOTDIR') {
      throw new Error(`Path is not a directory: ${dir}`);
    }
    throw err;
  }

