// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR  = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION   = '.sql';
const DEFAULT_ENV_FILE = '.env.test';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Minimal .env parser — no third-party dependencies required.
 *
 * Handles:
 *   - KEY=value
 *   - KEY="quoted value"  /  KEY='quoted value'
 *   - Inline # comments (outside quotes)
 *   - Blank lines and lines that start with #
 *
 * Only keys explicitly listed in `allowedKeys` are extracted; every other
 * line is skipped entirely so unrelated secrets are never loaded into memory.
 *
 * @param {string}   filePath    - Path to the .env file.
 * @param {string[]} allowedKeys - Whitelist of variable names to extract.
 * @returns {Record<string, string>} Map of allowed key → value pairs found.
 */
function parseEnvFile(filePath, allowedKeys) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const allowed = new Set(allowedKeys);
  const result  = {};

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const rawLine of lines) {
    const line = rawLine.trim();

    // Skip blanks and full-line comments
    if (line === '' || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();

    // Skip keys we don't need — their values are never read
    if (!allowed.has(key)) continue;

    let value = line.slice(eqIndex + 1).trim();

    // Strip inline comment (only when value is not quoted)
    if (value[0] !== '"' && value[0] !== "'") {
      const commentIdx = value.indexOf(' #');
      if (commentIdx !== -1) value = value.slice(0, commentIdx).trim();
    } else {
      // Strip matching surrounding quotes
      const quote = value[0];
      if (value.endsWith(quote) && value.length >= 2) {
        value = value.slice(1, -1);
      }
    }

    result[key] = value;
  }

  return result;
}

/**
 * Parses a postgres:// (or postgresql://) connection URL and returns its
 * structural parts so we can build a redacted summary for logging.
 *
 * Supports the standard form:
 *   protocol://user:password@host:port/database
 *
 * @param {string} url - The raw DATABASE_URL value.
 * @returns {{ protocol: string, user: string, host: string, port: string, database: string }}
 * @throws {Error} When the URL cannot be parsed.
 */
function parseConnectionUrl(url) {
  // Use the WHATWG URL API — available in Node.js ≥ 10 with no extra deps.
  // postgres:// is not a registered scheme in browsers, but Node's URL handles it.
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error('DATABASE_URL is not a valid URL. Expected format: protocol://user:password@host:port/database');
  }

  const protocol = parsed.protocol.replace(/:$/, ''); // strip trailing colon
  const user     = parsed.username || '(none)';
  const host     = parsed.hostname || '(none)';
  const port     = parsed.port     || '(default)';
  const database = (parsed.pathname || '/').replace(/^\//, '') || '(none)';

  return { protocol, user, host, port, database };
}

/**
