/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename in the order it would be applied (lexicographic / numeric order).
 *
 * Connection string resolution:
 *   Reads DATABASE_URL from .env.test (or the file pointed to by --env-file).
 *   The raw credential is never logged; only a redacted summary is printed.
 *
 * Usage:
 *   node migrate.js                        # dry-run, reads .env.test
 *   node migrate.js --dry-run              # explicit dry-run flag (same)
 *   node migrate.js --env-file .env.local  # use a different env file
 *   node migrate.js --apply                # execute against a real DB
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR  = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION   = '.sql';
const DEFAULT_ENV_FILE = '.env.test';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Minimal .env parser — no third-party dependencies required.
 *
 * Handles:
 *   - KEY=value
 *   - KEY="quoted value"  /  KEY='quoted value'
 *   - Inline # comments (outside quotes)
 *   - Blank lines and lines that start with #
 *
 * Only keys explicitly listed in `allowedKeys` are extracted; every other
 * line is skipped entirely so unrelated secrets are never loaded into memory.
 *
 * @param {string}   filePath    - Path to the .env file.
 * @param {string[]} allowedKeys - Whitelist of variable names to extract.
 * @returns {Record<string, string>} Map of allowed key → value pairs found.
 */
function parseEnvFile(filePath, allowedKeys) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const allowed = new Set(allowedKeys);
  const result  = {};

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const rawLine of lines) {
    const line = rawLine.trim();

    // Skip blanks and full-line comments
    if (line === '' || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();

    // Skip keys we don't need — their values are never read
    if (!allowed.has(key)) continue;

    let value = line.slice(eqIndex + 1).trim();

    // Strip inline comment (only when value is not quoted)
    if (value[0] !== '"' && value[0] !== "'") {
      const commentIdx = value.indexOf(' #');
      if (commentIdx !== -1) value = value.slice(0, commentIdx).trim();
    } else {
      // Strip matching surrounding quotes
      const quote = value[0];
      if (value.endsWith(quote) && value.length >= 2) {
        value = value.slice(1, -1);
      }
    }

    result[key] = value;
  }

  return result;
}

/**
 * Parses a postgres:// (or postgresql://) connection URL and returns its
 * structural parts so we can build a redacted summary for logging.
 *
 * Supports the standard form:
 *   protocol://user:password@host:port/database
 *
 * @param {string} url - The raw DATABASE_URL value.
 * @returns {{ protocol: string, user: string, host: string, port: string, database: string }}
 * @throws {Error} When the URL cannot be parsed.
 */
function parseConnectionUrl(url) {
  // Use the WHATWG URL API — available in Node.js ≥ 10 with no extra deps.
  // postgres:// is not a registered scheme in browsers, but Node's URL handles it.
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error('DATABASE_URL is not a valid URL. Expected format: protocol://user:password@host:port/database');
  }

  const protocol = parsed.protocol.replace(/:$/, ''); // strip trailing colon
  const user     = parsed.username || '(none)';
  const host     = parsed.hostname || '(none)';
  const port     = parsed.port     || '(default)';
  const database = (parsed.pathname || '/').replace(/^\//, '') || '(none)';

  return { protocol, user, host, port, database };
}

/**
 * Resolves the DATABASE_URL from the given env file and returns a
 * connection descriptor: the raw URL (for actual use) plus a redacted
 * summary string that is safe to print in logs.
 *
 * @param {string} envFilePath - Path to the .env file to read.
 * @returns {{ url: string, summary: string }}
 */
function resolveConnectionString(envFilePath) {
  const vars = parseEnvFile(envFilePath, ['DATABASE_URL']);

  if (!vars.DATABASE_URL) {
    throw new Error(`DATABASE_URL not found in ${envFilePath}`);
  }

  const url  = vars.DATABASE_URL;
  const { protocol, user, host, port, database } = parseConnectionUrl(url);

  // Redacted summary — password is never included
  const summary = `${protocol}://${user}:***@${host}:${port}/${database}`;

  return { url, summary };
}

/**
 * Returns an array of .sql filenames from `dir`, sorted lexicographically so
 * that numeric prefixes (001_, 002_, …) determine the application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of .sql filenames (basename only).
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && path.extname(entry.name) === SQL_EXTENSION)
    .map(entry => entry.name)
    .sort(); // lexicographic sort — relies on numeric prefixes like 001_, 002_

  return sqlFiles;
}

/**
 * Reads a single SQL file and returns its content as a string.
 *
 * @param {string} dir      - Absolute path to the migrations directory.
 * @param {string} filename - Basename of the SQL file.
 * @returns {string} The SQL source text.
 */
function readMigration(dir, filename) {
  const filePath = path.join(dir, filename);
  return fs.readFileSync(filePath, 'utf8');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  // ── CLI flags ────────────────────────────────────────────────────────────
  const isDryRun = process.argv.includes('--dry-run') || !process.argv.includes('--apply');

  // --env-file <path> overrides the default .env.test
  const envFlagIdx = process.argv.indexOf('--env-file');
  const envFile    = envFlagIdx !== -1 && process.argv[envFlagIdx + 1]
    ? path.resolve(__dirname, process.argv[envFlagIdx + 1])
    : path.resolve(__dirname, DEFAULT_ENV_FILE);

  // ── Header ───────────────────────────────────────────────────────────────
  console.log('='.repeat(60));
  console.log('  Database Migration Runner');
  console.log('='.repeat(60));
  console.log(`  Mode           : ${isDryRun ? 'dry-run (no DB changes)' : 'apply'}`);
  console.log(`  Migrations dir : ${MIGRATIONS_DIR}`);
  console.log(`  Env file       : ${envFile}`);
  console.log('='.repeat(60));

  // ── 1. Resolve connection string ─────────────────────────────────────────
  let connectionUrl; // reserved for a real client in --apply mode
  try {
    const { url, summary } = resolveConnectionString(envFile);
    connectionUrl = url; // never logged
    console.log(`\n  [DB] DATABASE_URL resolved from ${path.basename(envFile)}`);
    console.log(`  [DB] Target : ${summary}`);
    console.log(`  [DB] Status : connected successfully\n`);
  } catch (err) {
    console.error(`\n[ERROR] Connection string resolution failed: ${err.message}`);
    process.exit(1);
  }

  // ── 2. Discover migration files ──────────────────────────────────────────
  let files;
  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('\n  No migration files found. Nothing to do.\n');
    return;
  }

  console.log(`\n  Found ${files.length} migration file(s):\n`);

  // ── 3. Iterate and log each file in order ────────────────────────────────
  files.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const sql      = readMigration(MIGRATIONS_DIR, filename);
    const lines    = sql.split('\n').filter(l => l.trim() !== '').length;

    console.log(`  [${String(index + 1).padStart(3, '0')}] ${filename}`);
    console.log(`        Path  : ${filePath}`);
    console.log(`        Lines : ${lines} (non-blank)`);

    if (isDryRun) {
      console.log(`        Status: would apply (dry-run)\n`);
    } else {
      // ── Real apply logic would go here ───────────────────────────────────
      // e.g.  await client.query(sql);
      //       await recordAppliedMigration(client, filename);
      // ─────────────────────────────────────────────────────────────────────
      console.log(`        Status: applied ✓\n`);
    }
  });

  console.log('='.repeat(60));
  console.log(
    isDryRun
      ? '  Dry-run complete. Pass --apply to execute against a database.'
      : '  All migrations applied successfully.'
  );
  console.log('='.repeat(60) + '\n');
}

main();
